3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import jakarta.validation.Valid;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
14	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
15	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
16	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
17	import org.springframework.validation.annotation.Validated;
18	import org.springframework.web.bind.annotation.RequestBody;
19	
20	@Validated
21	public class BuildOwner {
22	
23	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
24	            Out<Boolean> sharesHousehold)
25	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
26	            InvalidPostcodeException, FutureRegistrationDateException {
27	        // Publish the request-only 'sharesHousehold' flag for the household duplicate check.
28	        // Not part of the Owner entity, so it travels as a separate variable.
29	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
30	        // Normalize the address up front so the required-field check below rejects an address that
31	        // is blank once normalized, and every later comparison sees the stored normalized form.
32	        request.setAddress(Addresses.normalize(request.getAddress()));
33	        List<String> missing = new ArrayList<>();
34	        if (isBlank(request.getFirstName())) {
35	            missing.add("firstName");
36	        }
37	        if (isBlank(request.getLastName())) {
38	            missing.add("lastName");
39	        }
40	        if (isBlank(request.getAddress())) {
41	            missing.add("address");
42	        }
43	        if (isBlank(request.getCity())) {
44	            missing.add("city");
45	        }
46	        if (isBlank(request.getTelephone())) {
47	            missing.add("telephone");
48	        }
49	        if (!missing.isEmpty()) {
50	            throw new MissingOwnerFieldsException(missing);
51	        }
52	        // Normalize the telephone to E.164 form (keep '+'/country code, else assume '+61').
53	        request.setTelephone(Telephones.toE164(request.getTelephone()));
54	        // Email is optional; when present it must be syntactically valid and is stored lower-cased.
55	        request.setEmail(OwnerEmails.normalize(request.getEmail()));
56	        // Postcode is optional; when present it must be valid for the city's region
57	        // (a city with no known region accepts any 4-digit postcode). The 4-digit shape
58	        // is enforced by the request schema, so only the region range is checked here.
59	        Postcodes.validate(request.getCity(), request.getPostcode());
60	        Owner owner = ownerMapper.toOwner(request);
61	        // The effective registration date is the supplied value, or the server's current date when
62	        // none is supplied. Either way it must fall on a business day: a Saturday or Sunday rolls
63	        // forward to the next Monday. Everything derived from the registration date (membership
64	        // number year, daily create-limit) then sees this adjusted business day.
65	        LocalDate registrationDate = owner.getRegistrationDate();
66	        if (registrationDate == null) {
67	            registrationDate = LocalDate.now();
68	        } else if (registrationDate.isAfter(LocalDate.now())) {
69	            // A supplied registration date may not be in the future.
70	            throw new FutureRegistrationDateException(
71	                    "registrationDate " + registrationDate + " is later than the server date");
72	        }
73	        owner.setRegistrationDate(toBusinessDay(registrationDate));
74	        built.set(owner);
75	    }
76	
77	    /** Roll a weekend date forward to the next Monday; business days are returned unchanged. */
78	    private static LocalDate toBusinessDay(LocalDate date) {
79	        return switch (date.getDayOfWeek()) {
80	            case SATURDAY -> date.plusDays(2);
81	            case SUNDAY -> date.plusDays(1);
82	            default -> date;
83	        };
84	    }
85	
86	    private static boolean isBlank(String value) {
87	        return value == null || value.isBlank();
88	    }
89	}
