1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared handling for the owner {@code address}. Addresses are stored in a normalized form:
8	 * surrounding whitespace is trimmed, runs of internal whitespace collapse to a single space,
9	 * the text is upper-cased and common street-type abbreviations are expanded
10	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
11	 *
12	 * <p>So {@code '  12  main  st '} is stored as {@code '12 MAIN STREET'}.
13	 */
14	final class Addresses {
15	
16	    // Common street-type abbreviations expanded to their full word (compared upper-cased).
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
19	
20	    private Addresses() {
21	    }
22	
23	    /**
24	     * Normalize an address: trim, collapse whitespace, upper-case and expand common
25	     * abbreviations. Returns an empty string for a {@code null} or blank value.
26	     */
27	    static String normalize(String address) {
28	        if (address == null) {
29	            return "";
30	        }
31	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        StringBuilder sb = new StringBuilder(collapsed.length());
37	        for (int i = 0; i < tokens.length; i++) {
38	            if (i > 0) {
39	                sb.append(' ');
40	            }
41	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
42	        }
43	        return sb.toString();
44	    }
45	}
