3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	
7	/**
8	 * Validates an owner's optional 4-digit postcode against the fixed region ranges,
9	 * keyed by the city's region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD): NSW
10	 * 2000-2099, VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any
11	 * 4-digit postcode. Validation is skipped when no postcode is supplied.
12	 */
13	final class Postcodes {
14	
15	    private Postcodes() {
16	    }
17	
18	    /** Fixed city-to-region table (mirrors the read-only {@code locality} mapping). */
19	    private static final Map<String, String> CITY_REGION = Map.of(
20	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
21	
22	    /** Region -> inclusive 4-digit postcode range {low, high}. */
23	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
24	            "NSW", new int[] {2000, 2099},
25	            "VIC", new int[] {3000, 3099},
26	            "QLD", new int[] {4000, 4099});
27	
28	    /**
29	     * Validate the supplied postcode for the given city. A blank/absent postcode is a
30	     * no-op (postcode is optional). A city with no known region accepts any 4-digit
31	     * postcode. When the city's region is known, the postcode must fall within that
32	     * region's inclusive range, otherwise an {@link InvalidPostcodeException} is thrown.
33	     */
34	    static void validate(String city, String postcode) throws InvalidPostcodeException {
35	        if (postcode == null || postcode.isBlank()) {
36	            return;
37	        }
38	        String region = CITY_REGION.get(city);
39	        if (region == null) {
40	            return; // unknown region accepts any 4-digit postcode
41	        }
42	        int[] range = REGION_POSTCODES.get(region);
43	        int value;
44	        try {
45	            value = Integer.parseInt(postcode.trim());
46	        }
47	        catch (NumberFormatException ex) {
48	            throw new InvalidPostcodeException(
49	                    "Postcode '" + postcode + "' must be four digits");
50	        }
51	        if (value < range[0] || value > range[1]) {
52	            throw new InvalidPostcodeException("Postcode '" + postcode + "' is not valid for "
53	                    + city + " (" + region + " expects " + range[0] + "-" + range[1] + ")");
54	        }
55	    }
56	}
