59	                .size(owner, ownerRepository);
60	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
61	                .membershipPoints(owner, householdSize);
62	    }
63	
64	    /**
65	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
66	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
67	     */
68	    protected int membershipLevel(Owner owner) {
69	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
70	                .membershipLevel(membershipPoints(owner));
71	    }
72	
73	    /**
74	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
75	     * present (non-null and non-blank), otherwise {@code PHONE}.
76	     */
77	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
79	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
80	    }
81	
82	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
83	    private static final int ADULT_AGE = 18;
84	
85	    /** The age (in years) at which an owner becomes a senior. */
86	    private static final int SENIOR_AGE = 65;
87	
88	    /**
89	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
90	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
91	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
92	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
93	     * either the birth date or the registration date is absent, so an owner created
94	     * without a birth date has no age band.
95	     */
96	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
97	        LocalDate birthDate = owner.getBirthDate();
98	        LocalDate registrationDate = owner.getRegistrationDate();
99	        if (birthDate == null || registrationDate == null) {
100	            return null;
101	        }
102	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
103	        if (age < ADULT_AGE) {
104	            return OwnerDto.AgeBandEnum.MINOR;
105	        }
106	        if (age < SENIOR_AGE) {
107	            return OwnerDto.AgeBandEnum.ADULT;
108	        }
109	        return OwnerDto.AgeBandEnum.SENIOR;
110	    }
111	
112	    /**
113	     * Derives the owner's {@code locality} (canonical region string) from the
114	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
115	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
116	     * fall back to deriving the region directly from postcode, then city, then
