9	
10	/**
11	 * Builds and interprets the owner {@code customerCode}, the single region-and-hash identity every
12	 * derived value (membership number, its check digit, the create audit line and the {@code locality})
13	 * now hangs off.
14	 *
15	 * <p>The code is {@code <REGION>-<HASH8>} where REGION is the {@link #region(Owner) region} derived
16	 * from the owner's postcode (falling back to the city, then {@code "UNKNOWN"}) and HASH8 is the first
17	 * eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}. Sequence
18	 * numbers are no longer part of the identity, so the code depends only on the owner's own fields.
19	 */
20	public final class CustomerCodes {
21	
22	    /** Fixed city-to-region table (mirrors the read-only {@code locality} mapping). */
23	    private static final Map<String, String> CITY_REGION = Map.of(
24	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    private CustomerCodes() {
33	    }
34	
35	    /** Builds the {@code <REGION>-<HASH8>} customer code for the owner. */
36	    public static String build(Owner owner) {
37	        return region(owner) + "-" + hash8(owner.getTelephone(), owner.getLastName());
38	    }
39	
40	    /**
41	     * The region for the owner: the region whose inclusive postcode range contains the owner's
42	     * postcode wins; otherwise the fixed city-to-region table ({@code Sydney->NSW, Melbourne->VIC,
43	     * Brisbane->QLD}); otherwise {@code "UNKNOWN"}.
44	     */
45	    public static String region(Owner owner) {
46	        String region = regionFromPostcode(owner.getPostcode());
47	        if (region != null) {
48	            return region;
49	        }
50	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
51	    }
52	
53	    /**
54	     * The REGION segment of a customer code (everything before the first {@code '-'}), or the whole
55	     * code when it contains no {@code '-'}. Returns {@code null} for a {@code null} code.
56	     */
57	    public static String regionOf(String customerCode) {
58	        if (customerCode == null) {
59	            return null;
60	        }
61	        int dash = customerCode.indexOf('-');
62	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
63	    }
64	
65	    /** First eight upper-case hex characters of {@code SHA-256(telephone + lastName)}. */
66	    private static String hash8(String telephone, String lastName) {
67	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
68	        MessageDigest digest;
69	        try {
70	            digest = MessageDigest.getInstance("SHA-256");
71	        }
72	        catch (NoSuchAlgorithmException ex) {
73	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
74	        }
75	        byte[] bytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
76	        StringBuilder hex = new StringBuilder(16);
77	        for (int i = 0; i < 4; i++) {
78	            hex.append(String.format("%02X", bytes[i]));
79	        }
80	        return hex.toString();
81	    }
82	
83	    /**
84	     * The region whose inclusive postcode range contains the given 4-digit postcode, or
85	     * {@code null} when the postcode is absent, non-numeric, or in no known range.
86	     */
87	    private static String regionFromPostcode(String postcode) {
88	        if (postcode == null || postcode.isBlank()) {
89	            return null;
90	        }
91	        int value;
92	        try {
93	            value = Integer.parseInt(postcode.trim());
94	        }
95	        catch (NumberFormatException ex) {
96	            return null;
97	        }
98	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
99	            int[] range = entry.getValue();
100	            if (value >= range[0] && value <= range[1]) {
101	                return entry.getKey();
102	            }
103	        }
104	        return null;
105	    }
106	}
