12	 * region derived from the owner's postcode (falling back to the city, then {@code "UNKNOWN"}) and
13	 * HASH8 is the first eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}.
14	 * The identity depends only on the owner's own fields; there are no sequence numbers.
15	 *
16	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
17	 * appended with the smallest {@code n} of 2 or more that makes it unique.
18	 */
19	public class AssignCustomerCode {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        String base = CustomerCodes.build(owner);
23	        Set<String> existing = new HashSet<>();
24	        for (Owner other : ownerRepository.findAll()) {
25	            if (other.getId() != null && other.getId().equals(owner.getId())) {
26	                continue;
27	            }
28	            if (other.getCustomerCode() != null) {
29	                existing.add(other.getCustomerCode());
30	            }
31	        }
32	        String code = base;
33	        for (int n = 2; existing.contains(code); n++) {
34	            code = base + "-" + n;
35	        }
36	        owner.setCustomerCode(code);
37	    }
38	}
