28	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
29	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
30	     * customer code or the registration date is absent (e.g. legacy seed owners). Mirrors the
31	     * {@code membershipNumber} exposed on the owner response.
32	     */
33	    private static String membershipNumber(Owner owner) {
34	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
35	            return null;
36	        }
37	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
38	    }
39	}
