41	    @Mapping(target = "locality", expression = "java(locality(owner))")
42	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
43	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
44	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
45	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
46	    @Mapping(target = "identityKey",
47	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
48	    @Mapping(target = "telephoneDisplay",
49	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
50	    public abstract OwnerDto toOwnerDto(Owner owner);
51	
52	    /**
53	     * The owner's {@code membershipPoints}: the raw loyalty score (see
54	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships}), built from a
55	     * present email, no namesakes, a household of 3 or more and tenure over 365 days.
56	     */
57	    protected int membershipPoints(Owner owner) {
58	        long householdSize = org.springframework.samples.petclinic.rest.function.owner.Households
59	                .size(owner, ownerRepository);
60	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
61	                .membershipPoints(owner, householdSize);
62	    }
63	
64	    /**
65	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
66	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
67	     */
68	    protected int membershipLevel(Owner owner) {
69	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
70	                .membershipLevel(membershipPoints(owner));
71	    }
