75	     * present (non-null and non-blank), otherwise {@code PHONE}.
76	     */
77	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
79	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
80	    }
81	
82	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
83	    private static final int ADULT_AGE = 18;
84	
85	    /** The age (in years) at which an owner becomes a senior. */
86	    private static final int SENIOR_AGE = 65;
87	
88	    /**
