90	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
91	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
92	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
93	     * either the birth date or the registration date is absent, so an owner created
94	     * without a birth date has no age band.
95	     */
96	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
97	        LocalDate birthDate = owner.getBirthDate();
98	        LocalDate registrationDate = owner.getRegistrationDate();
99	        if (birthDate == null || registrationDate == null) {
100	            return null;
101	        }
102	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
103	        if (age < ADULT_AGE) {
104	            return OwnerDto.AgeBandEnum.MINOR;
105	        }
106	        if (age < SENIOR_AGE) {
107	            return OwnerDto.AgeBandEnum.ADULT;
108	        }
109	        return OwnerDto.AgeBandEnum.SENIOR;
110	    }
